1	//! `remember` and `forget`.
2	//!
3	//! With a key, a write replaces the slot's current value (the old row is
4	//! closed, not deleted). Without one, a near-duplicate of a current memory
5	//! merges into it; anything merely similar is stored and reported back as
6	//! `related`, so the agent can decide whether one replaces the other.
7	
8	use std::collections::HashSet;
9	
10	use anyhow::{Context, Result, bail};
11	use rusqlite::{OptionalExtension, params};
12	use serde::Serialize;
13	
14	use super::guard::{self, Clean};
15	use super::{
16	    COLUMNS, Kind, Memory, MemoryRow, ensure_subject, get_row, insert_row, log, new_id, now, resolve_alias,
17	    row,
18	};
19	use crate::text::{Query, normalize_name, parse_unix, query_words};
20	
21	/// Word overlap at which two memories about the same subject are the same
22	/// claim.
23	const DUPLICATE: f64 = 0.8;
24	/// Word overlap worth pointing out.
25	const RELATED: f64 = 0.3;
26	
27	#[derive(Debug, Clone, Default)]
28	pub struct Remember {
29	    pub text: String,
30	    /// Default: `fact` with a key, `note` without.
31	    pub kind: Option<Kind>,
32	    pub subject: Option<String>,
33	    pub key: Option<String>,
34	    pub tags: Vec<String>,
35	    /// 1 (trivia) to 5 (critical); default 3.
36	    pub importance: Option<u8>,
37	    pub confidence: Option<f64>,
38	    pub source: Option<String>,
39	    /// Ids of related records in the data index, paths or URLs.
40	    pub refs: Vec<String>,
41	    pub pinned: bool,
42	    /// A date, or a duration from now (`12h`, `30d`, `6w`).
43	    pub expires: Option<String>,
44	    /// Other names for the subject.
45	    pub aliases: Vec<String>,
46	    /// Default: the configured namespace.
47	    pub ns: Option<String>,
48	}
49	
50	#[derive(Debug, Clone, Copy, PartialEq, Eq, Serialize)]
51	#[serde(rename_all = "snake_case")]
52	pub enum WriteStatus {
53	    Created,
54	    /// The slot's previous value was superseded.
55	    Replaced,
56	    /// Merged into an existing memory that says the same thing.
57	    Duplicate,
58	}
59	
60	#[derive(Debug, Serialize)]
61	pub struct WriteOutcome {
62	    pub status: WriteStatus,
63	    pub memory: MemoryRow,
64	    #[serde(skip_serializing_if = "Option::is_none")]
65	    pub replaced: Option<MemoryRow>,
66	    #[serde(skip_serializing_if = "Vec::is_empty")]
67	    pub related: Vec<MemoryRow>,
68	}
69	
70	impl WriteOutcome {
71	    pub fn render(&self) -> String {
72	        let now = now();
73	        let mut out = match self.status {
74	            WriteStatus::Created => format!("remembered {}\n", self.memory.id),
75	            WriteStatus::Replaced => format!("remembered {} (replaced the previous value)\n", self.memory.id),
76	            WriteStatus::Duplicate => format!("already known: merged into {}\n", self.memory.id),
77	        };
78	        out.push_str(&format!("  {}\n", self.memory.line(&now, false)));
79	        if let Some(old) = &self.replaced {
80	            out.push_str(&format!("  was: {}\n", old.line(&now, false)));
81	        }
82	        if !self.related.is_empty() {
83	            out.push_str("related (if one of these is now wrong, forget it or give both the same key):\n");
84	            for m in &self.related {
85	                out.push_str(&format!("  {}\n", m.line(&now, false)));
86	            }
87	        }
88	        out
89	    }
90	}
91	
92	#[derive(Debug, Clone, Default)]
93	pub struct Forget {
94	    pub id: Option<String>,
95	    pub subject: Option<String>,
96	    pub key: Option<String>,
97	    pub ns: Option<String>,
98	    pub reason: Option<String>,
99	}
100	
101	fn word_set(text: &str) -> HashSet<String> {
102	    query_words(text)
103	        .map(|w| {
104	            if w.len() > 3 && w.ends_with('s') && !w.ends_with("ss") {
105	                w[..w.len() - 1].to_string()
106	            } else {
107	                w
108	            }
109	        })
110	        .collect()
111	}
112	
113	fn jaccard(a: &HashSet<String>, b: &HashSet<String>) -> f64 {
114	    if a.is_empty() && b.is_empty() {
115	        return 1.0;
116	    }
117	    a.intersection(b).count() as f64 / a.union(b).count() as f64
118	}
119	
120	fn merge_lists(a: &[String], b: &[String]) -> Vec<String> {
121	    let mut out = a.to_vec();
122	    out.extend(b.iter().filter(|x| !a.contains(x)).cloned());
123	    out
124	}
125	
126	impl Memory {
127	    pub fn remember(&mut self, req: &Remember) -> Result<WriteOutcome> {
128	        let now = now();
129	        let c: Clean = guard::check(req, &self.settings, parse_unix(&now).unwrap_or(0))?;
130	        let tx = self.write_tx()?;
131	
132	        let (subject, subject_norm) = match &c.subject {
133	            Some(s) => {
134	                let norm = resolve_alias(&tx, &c.ns, &normalize_name(s))?;
135	                (Some(ensure_subject(&tx, &c.ns, s, &norm)?), norm)
136	            }
137	            None => (None, String::new()),
138	        };
139	        for alias in &c.aliases {
140	            let a = normalize_name(alias);
141	            if a != subject_norm {
142	                tx.execute(
143	                    "INSERT INTO subject_aliases (ns, alias, norm) VALUES (?1, ?2, ?3) \
144	                     ON CONFLICT (ns, alias) DO UPDATE SET norm = excluded.norm",
145	                    params![c.ns, a, subject_norm],
146	                )?;
147	            }
148	        }
149	
150	        let fresh = MemoryRow {
151	            id: new_id(),
152	            ns: c.ns.clone(),
153	            kind: c.kind,
154	            subject,
155	            key: c.key.clone(),
156	            text: c.text.clone(),
157	            tags: c.tags.clone(),
158	            importance: c.importance,
159	            confidence: c.confidence,
160	            source: c.source.clone(),
161	            refs: c.refs.clone(),
162	            pinned: c.pinned,
163	            created_at: now.clone(),
164	            updated_at: now.clone(),
165	            valid_from: now.clone(),
166	            valid_to: None,
167	            superseded_by: None,
168	            expires_at: c.expires_at.clone(),
169	            deleted_at: None,
170	            recall_count: 0,
171	            last_recalled_at: None,
172	        };
173	        let words = word_set(&c.text);
174	
175	        let outcome = if let Some(key) = &c.key {
176	            let current: Option<MemoryRow> = tx
177	                .prepare_cached(&format!(
178	                    "SELECT {COLUMNS} FROM memories WHERE ns = ?1 AND subject_norm = ?2 AND key = ?3 \
179	                     AND valid_to IS NULL AND deleted_at IS NULL"
180	                ))?
181	                .query_row(params![c.ns, subject_norm, key], row)
182	                .optional()?;
183	            match current {
184	                Some(old) if jaccard(&word_set(&old.text), &words) >= 1.0 && old.kind == c.kind => {
185	                    let merged = merge(&tx, &old, &c, req, &now)?;
186	                    WriteOutcome {
187	                        status: WriteStatus::Duplicate,
188	                        memory: merged,
189	                        replaced: None,
190	                        related: vec![],
191	                    }
192	                }
193	                Some(mut old) => {
194	                    tx.execute(
195	                        "UPDATE memories SET valid_to = ?2, superseded_by = ?3 WHERE id = ?1",
196	                        params![old.id, now, fresh.id],
197	                    )?;
198	                    old.valid_to = Some(now.clone());
199	                    old.superseded_by = Some(fresh.id.clone());
200	                    insert_row(&tx, &fresh)?;
201	                    log(
202	                        &tx,
203	                        "supersede",
204	                        Some(&fresh.id),
205	                        &serde_json::json!({"memory": fresh, "replaced": old.id}),
206	                    )?;
207	                    WriteOutcome {
208	                        status: WriteStatus::Replaced,
209	                        memory: fresh,
210	                        replaced: Some(old),
211	                        related: vec![],
212	                    }
213	                }
214	                None => {
215	                    insert_row(&tx, &fresh)?;
216	                    log(&tx, "remember", Some(&fresh.id), &serde_json::to_value(&fresh)?)?;
217	                    WriteOutcome {
218	                        status: WriteStatus::Created,
219	                        memory: fresh,
220	                        replaced: None,
221	                        related: vec![],
222	                    }
223	                }
224	            }
225	        } else {
226	            let mut similar: Vec<(f64, MemoryRow)> =
227	                similar(&tx, &c.ns, c.subject.as_ref().map(|_| subject_norm.as_str()), &c.text)?
228	                    .into_iter()
229	                    .map(|m| (jaccard(&word_set(&m.text), &words), m))
230	                    .collect();
231	            similar.sort_by(|a, b| b.0.total_cmp(&a.0));
232	            match similar.first() {
233	                Some((score, best)) if *score >= DUPLICATE && best.key.is_none() => {
234	                    let merged = merge(&tx, best, &c, req, &now)?;
235	                    WriteOutcome {
236	                        status: WriteStatus::Duplicate,
237	                        memory: merged,
238	                        replaced: None,
239	                        related: vec![],
240	                    }
241	                }
242	                _ => {
243	                    insert_row(&tx, &fresh)?;
244	                    log(&tx, "remember", Some(&fresh.id), &serde_json::to_value(&fresh)?)?;
245	                    let related =
246	                        similar.into_iter().filter(|(s, _)| *s >= RELATED).take(3).map(|(_, m)| m).collect();
247	                    WriteOutcome { status: WriteStatus::Created, memory: fresh, replaced: None, related }
248	                }
249	            }
250	        };
251	        tx.commit()?;
252	        Ok(outcome)
253	    }
254	
255	    /// Soft delete: the row stays (marked forgotten) until `prune`.
256	    pub fn forget(&mut self, f: &Forget) -> Result<MemoryRow> {
257	        let now = now();
258	        let ns = guard::namespace(f.ns.as_deref().unwrap_or(&self.settings.namespace))?;
259	        let tx = self.write_tx()?;
260	        let target = match (&f.id, &f.key) {
261	            (Some(id), _) => get_row(&tx, id)?.with_context(|| format!("no memory with id {id:?}"))?,
262	            (None, Some(key)) => {
263	                let norm = match &f.subject {
264	                    Some(s) => resolve_alias(&tx, &ns, &normalize_name(s))?,
265	                    None => String::new(),
266	                };
267	                let key = guard::key(key)?;
268	                tx.prepare_cached(&format!(
269	                    "SELECT {COLUMNS} FROM memories WHERE ns = ?1 AND subject_norm = ?2 AND key = ?3 \
270	                     AND valid_to IS NULL AND deleted_at IS NULL"
271	                ))?
272	                .query_row(params![ns, norm, key], row)
273	                .optional()?
274	                .with_context(|| {
275	                    format!(
276	                        "nothing current for key {key:?}{} in {ns}",
277	                        f.subject.as_deref().map(|s| format!(" of {s:?}")).unwrap_or_default()
278	                    )
279	                })?
280	            }
281	            _ => bail!("pass a memory id, or a key (with its subject)"),
282	        };
283	        if target.deleted_at.is_some() {
284	            bail!("{} was already forgotten", target.id);
285	        }
286	        tx.execute(
287	            "UPDATE memories SET deleted_at = ?2, updated_at = ?2 WHERE id = ?1",
288	            params![target.id, now],
289	        )?;
290	        log(&tx, "forget", Some(&target.id), &serde_json::json!({"reason": f.reason}))?;
291	        let forgotten = get_row(&tx, &target.id)?.context("forgotten row vanished")?;
292	        tx.commit()?;
293	        Ok(forgotten)
294	    }
295	}
296	
297	/// Current memories that share words with `text`, best BM25 first.
298	fn similar(
299	    conn: &rusqlite::Connection,
300	    ns: &str,
301	    subject_norm: Option<&str>,
302	    text: &str,
303	) -> Result<Vec<MemoryRow>> {
304	    let mut seen = HashSet::new();
305	    let q =
306	        Query { words: query_words(text).filter(|w| seen.insert(w.clone())).collect(), ..Default::default() };
307	    let Some(expr) = q.fts() else { return Ok(Vec::new()) };
308	    let cols = COLUMNS.split(", ").map(|c| format!("m.{c}")).collect::<Vec<_>>().join(", ");
309	    let subject_sql = if subject_norm.is_some() { "AND m.subject_norm = ?3" } else { "AND ?3 IS NULL" };
310	    let mut stmt = conn.prepare_cached(&format!(
311	        "SELECT {cols} FROM memory_fts JOIN memories AS m ON m.rowid = memory_fts.rowid \
312	         WHERE memory_fts MATCH ?1 AND m.ns = ?2 {subject_sql} AND m.valid_to IS NULL AND m.deleted_at IS NULL \
313	         ORDER BY memory_fts.rank LIMIT 20"
314	    ))?;
315	    Ok(stmt.query_map(params![expr, ns, subject_norm], row)?.collect::<rusqlite::Result<_>>()?)
316	}
317	
318	/// Fold a restatement into the existing memory: it is reaffirmed (fresh
319	/// `updated_at`), a little more important, and keeps every tag and ref.
320	fn merge(
321	    conn: &rusqlite::Connection,
322	    old: &MemoryRow,
323	    c: &Clean,
324	    req: &Remember,
325	    now: &str,
326	) -> Result<MemoryRow> {
327	    let importance = (old.importance + 1).min(5).max(req.importance.unwrap_or(0)).max(old.importance);
328	    let tags = merge_lists(&old.tags, &c.tags);
329	    let refs = merge_lists(&old.refs, &c.refs);
330	    conn.execute(
331	        "UPDATE memories SET importance = ?2, pinned = pinned OR ?3, tags = ?4, refs = ?5, updated_at = ?6, \
332	         confidence = MAX(confidence, ?7), expires_at = COALESCE(?8, expires_at) WHERE id = ?1",
333	        params![
334	            old.id,
335	            importance,
336	            c.pinned,
337	            tags.join(" "),
338	            serde_json::to_string(&refs)?,
339	            now,
340	            c.confidence,
341	            c.expires_at
342	        ],
343	    )?;
344	    let merged = get_row(conn, &old.id)?.context("merged row vanished")?;
345	    log(conn, "merge", Some(&old.id), &serde_json::json!({"text": c.text, "source": c.source}))?;
346	    Ok(merged)
347	}
